#!/usr/bin/env bash
# Full regression (Node/jsdom/Python parts). Usage: bash run-regression.sh <timestamp>  (run from tests/). Browser tests (browser-chrome.js, test-paging-chrome.js) are run separately.
cd "$(dirname "$0")" || exit 9; C3T=$(mktemp -d); git -C .. archive c4-base 2>/dev/null | tar -x -C $C3T && export C3_TREE=$C3T; P2T=$(mktemp -d); git -C .. archive v0.6-candidate-4-phase2 2>/dev/null | tar -x -C $P2T; P1T=$(mktemp -d); git -C .. archive v0.6-candidate-4-phase1-final 2>/dev/null | tar -x -C $P1T && export P1_TREE=$P1T; TS=${1:-$(date -u +%Y%m%dT%H%M%SZ)}; L=logs/regression-$TS.log; rc=0
{ echo "# regression $TS  node $(node -v)"
  run(){ n="$1"; shift; out=$("$@" 2>&1); c=$?; echo "$n | exit $c | $(echo "$out" | grep -E "(summary [0-9]+ pass|[0-9]+ passed, [0-9]+ failed|ALL SECTIONS IDENTICAL|section\(s\) differ|[0-9]+ pass [0-9]+ fail)" | tail -1)"; [ $c -eq 0 ] || { rc=1; echo "$out" | grep -E "^FAIL|DIFFERENT" | head -5; }; }
  for tz in UTC Europe/London; do echo "## TZ=$tz"; for t in test7 test8 test9 domtest domtest2 test-failed-import test-export-nohistory test-timezones test-po-edge test-structure test-paging test-fillcap test-export-repeat test-cache test-phase1 test-blank-qty test-uom test-missing-values test-fglt-note test-forecast-conf test-supplier-eligibility test-na-constraints; do TZ=$tz run "$t" node $t.js; done; done
  echo "## static"; run check-globals node check-globals.js
  echo "## independent Python verifier (Northstar)"; node dump.js >/dev/null 2>&1; python3 verify.py 2>&1 | tail -1; rm -f dump.json 
  echo "## supplier scenarios"; bash run-supplier-scenarios.sh $TS | grep overall; bash run-edge-scenarios.sh $TS; [ $? -eq 0 ] || rc=1
  echo "## golden snapshots"; for tz in UTC Europe/London America/New_York Asia/Kolkata Pacific/Auckland; do TZ=$tz node regress.js .. logs/regress-$TS-${tz//\//_}.json >/dev/null 2>&1; for s in snapshots/v0.5-golden-20261105T101953Z.json snapshots/v0.6.0-baseline-20261109T152050Z.json; do echo "$tz vs $(basename $s): $(node compare-snapshots.js $s logs/regress-$TS-${tz//\//_}.json | tail -1)"; done; TZ=$tz node regress.js $P2T logs/regress-p2-$TS-${tz//\//_}.json >/dev/null 2>&1; echo "$tz vs PHASE 2 (primary baseline): $(node compare-snapshots.js logs/regress-p2-$TS-${tz//\//_}.json logs/regress-$TS-${tz//\//_}.json | tail -1)"; done
  echo "# overall exit $rc"; } > $L 2>&1; cat $L; exit $rc
